// Pipeline Stage Intermediate Registers (MIPS 5-Stage Model)

// IF (Fetch) -> ID (Decode)
struct IF_ID_Reg {
    unsigned int instruction;
    int next_PC;
};

// ID (Decode) -> EX (Execute)
struct ID_EX_Reg {
    int regA_val, regB_val;
    int immediate;
    int dest_reg_idx; // For hazard detection/forwarding
};

// EX (Execute) -> MEM (Memory)
struct EX_MEM_Reg {
    int ALU_Result;
    int value_to_write; // Used by Store ops
};

// MEM (Memory) -> WB (Write Back)
struct MEM_WB_Reg {
    int read_data;
    int WB_Result;
    int final_dest_idx;
};
